class Solution {
public:
    vector<string> summaryRanges(vector<int>& nums) {
        vector<string> ans;
        int n=nums.size();
        for(int i=0;i<nums.size();)
        {
            int start=i;
            int end=i;
            while(end+1<n and nums[end+1]==nums[end]+1)
                end+=1;
            if(end>start)
                ans.push_back(to_string(nums[start])+"->"+to_string(nums[end]));
            else
                ans.push_back(to_string(nums[start]));
            i=end+1;
        }
        return ans;
    }
};

class Solution:
    # @param {integer[]} nums
    # @return {string[]}
    def summaryRanges(self, nums):
        if not nums:
            return []
        results = []
        start = None
        for i, n in enumerate(nums):
            if start is None:
                start = n
                continue
            if n > nums[i-1]+1:
                if nums[i-1] == start:
                    results.append(str(start))
                else:
                    results.append("%d->%d"%(start, nums[i-1]))
                start = n
        if nums[i] == start:
            results.append(str(start))
        else:
            results.append("%d->%d"%(start, nums[i]))
        return results

class Solution(object):
    def summaryRanges(self, nums):
        """
        :type nums: List[int]
        :rtype: List[str]
        """
        n = len(nums)
        p = 0
        ans = []
        while p < len(nums):
            s = p
            while p + 1 < n and nums[p + 1] == nums[p] + 1:
                p += 1
            if p == s:
                ans.append(str(nums[s]))
            else:
                ans.append(str(nums[s]) + "->" + str(nums[p]))
            p += 1
        return ans
